contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Parameters:
    // from: source address (must not be zero)
    // to: destination address (must not be zero)
    // tokenId: id to transfer
    // amount: quantity to transfer
    // We exercise safeTransferFrom and assert the invariant about total outstanding tokens per id
    function run(address from, address to, uint256 tokenId, uint256 amount) public payable {
        require(from != address(0) && to != address(0));
        // Observe pre-state: total of tokenId across two addresses (we can only call balanceOf per account)
        uint256 balanceFromBefore = c.balanceOf(from, tokenId); if (__ESBMC_reverted()) return;
        uint256 balanceToBefore = c.balanceOf(to, tokenId); if (__ESBMC_reverted()) return;
        uint256 totalBefore = balanceFromBefore + balanceToBefore;

        // Attempt the transfer and record whether it reverted.
        bool reverted;
        c.safeTransferFrom(from, to, tokenId, amount, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe post-state
        uint256 balanceFromAfter = c.balanceOf(from, tokenId); if (__ESBMC_reverted()) return;
        uint256 balanceToAfter = c.balanceOf(to, tokenId); if (__ESBMC_reverted()) return;
        uint256 totalAfter = balanceFromAfter + balanceToAfter;

        // General rule:
        // - If the call reverted then balances for these two accounts did not change (since state must be unchanged on revert).
        // - If the call succeeded then the sum of balances for tokenId across these two accounts is unchanged (transfer conserves tokens).
        // Note: we only observe two accounts because only public getters are allowed; this still enforces conservation between these two holders,
        // and in combination with the require that from and to are concrete addresses, a faulty contract that burned/minted on transfer would violate this.
        assert(
            (reverted && balanceFromBefore == balanceFromAfter && balanceToBefore == balanceToAfter)
            || (!reverted && totalBefore == totalAfter)
        );
    }

    receive() external payable {}
}

