    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address from, address to, uint256 tokenId, uint256 amount) internal {
        vm.assume(from != address(0) && to != address(0));
        uint256 balanceFromBefore;
        try c.balanceOf(from, tokenId) returns (uint256 __r) { balanceFromBefore = __r; } catch { return; }
        uint256 balanceToBefore;
        try c.balanceOf(to, tokenId) returns (uint256 __r) { balanceToBefore = __r; } catch { return; }
        uint256 totalBefore = balanceFromBefore + balanceToBefore;
        bool reverted;
        try c.safeTransferFrom(from, to, tokenId, amount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceFromAfter;
        try c.balanceOf(from, tokenId) returns (uint256 __r) { balanceFromAfter = __r; } catch { return; }
